        "id": "medication-statement-1",
        "status": "stopped",
        "medicationCodeableConcept": {
          "text": "OTC hair regrowth drops"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Tried for approximately 1 week; dose and application instructions not stated."
          }
        ],
        "note": [
          {
            "text": "Stopped because there was no effect."
          }
        ]
      }
    },
